let winner = try await withThrowingTaskGroup(of: Offer.self) { group in
    for r in recipients { group.addTask { try await ask(r) } }
    group.addTask { try await Task.sleep(for: budget); throw GatherError.deadline }
    while let offer = try await group.next() {          // as they become ready
        if offer.isAcceptable { group.cancelAll(); return offer }
    }
    throw GatherError.noAnswer
}   // scope exit awaits or cancels whatever is left

